Lemma upush_neq : forall pc0 ra acc, ra <> pc0 -> upush pc0 ra acc = acc ++ [ra].
Proof. intros pc0 ra acc NE. unfold upush. destruct (Z.eqb_spec ra pc0); [contradiction| reflexivity]. Qed.

