  (* [comment removed for export] *)
  Theorem achain_utrace : forall m bp cur ra0 L,
    achain m cur L ->
    rw_cells bsegs m (bp - 16) [C8 (Z_to_bv 64 cur); C8 (Z_to_bv 64 ra0)] ->
    aceil <= bp -> 0 <= cur < 2^64 -> 0 <= ra0 < 2^64 ->
    exists CHu, frame_chain bsegs m top bp CHu
      /\ forall pc0 bot md, ~ In pc0 (ra0 :: map snd L) ->
